const updateServiceBundle = `-- name: UpdateServiceBundle :one
UPDATE service_bundles
SET name = $1, description = $2, price = $3,
    show_online = $4, is_active = $5, sort_order = $6
WHERE organization_id = $7 AND id = $8 AND deleted_at IS NULL
RETURNING id, uuid, organization_id, name, description, price, show_online, is_active, sort_order, created_at, updated_at, deleted_at
`

type UpdateServiceBundleParams struct {
	Name           string         `json:"name"`
	Description    string         `json:"description"`
	Price          pgtype.Numeric `json:"price"`
	ShowOnline     bool           `json:"show_online"`
	IsActive       bool           `json:"is_active"`
	SortOrder      int32          `json:"sort_order"`
	OrganizationID int64          `json:"organization_id"`
	ID             int64          `json:"id"`
}

func (q *Queries) UpdateServiceBundle(ctx context.Context, arg UpdateServiceBundleParams) (ServiceBundle, error) {
	row := q.db.QueryRow(ctx, updateServiceBundle,
		arg.Name,
		arg.Description,
		arg.Price,
		arg.ShowOnline,
		arg.IsActive,
		arg.SortOrder,
		arg.OrganizationID,
		arg.ID,
	)
	var i ServiceBundle
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.OrganizationID,
		&i.Name,
		&i.Description,
		&i.Price,
		&i.ShowOnline,
		&i.IsActive,
		&i.SortOrder,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
